import java.util.*;
import java.io.*;

public class CFA {
    BufferedReader inStream;
    PrintWriter outStream;
    StringTokenizer tokens;
    boolean isEOF;
    private static final long MOD = 998244353L;

    class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x; this.y = y;
        }
    }

    void execute() throws IOException {
        int n = getNextInt();
        int m = getNextInt();
        if (n > m) {
            int temp = n; n = m; m = temp;
        }

        if (n == 1) {
            m--;
            int[] pattern = {0, 0, 0, 2, 4, 6};
            long result = (m / 6) * 6 + pattern[m % 6];
            printLine(result);
            return;
        } else if (n == 2) {
            if (m < 20) {
                printLine(bruteforce(n, m));
            } else {
                printLine(1L * n * m);
            }
            return;
        } else if (n == 3) {
            if (m < 20) {
                printLine(bruteforce(n, m));
            } else {
                long res = 1L * n * m;
                if (res % 2 != 0) res--;
                printLine(res);
            }
            return;
        }

        long totalCells = (long) n * m;
        if (totalCells % 2 != 0) totalCells--;
        printLine(totalCells);
    }

    int bruteforce(int n, int m) {
        List<Point> evenPoints = new ArrayList<>();
        List<Point> oddPoints = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((i + j) % 2 == 0) {
                    evenPoints.add(new Point(i, j));
                } else {
                    oddPoints.add(new Point(i, j));
                }
            }
        }

        boolean[][] adjacency = new boolean[evenPoints.size()][oddPoints.size()];
        for (int i = 0; i < evenPoints.size(); i++) {
            for (int j = 0; j < oddPoints.size(); j++) {
                int dist = Math.abs(evenPoints.get(i).x - oddPoints.get(j).x) + Math.abs(evenPoints.get(i).y - oddPoints.get(j).y);
                if (dist == 3) {
                    adjacency[i][j] = true;
                }
            }
        }
        return 2 * maxMatching(adjacency);
    }

    int maxMatching(boolean[][] graph) {
        int n1 = graph.length;
        int n2 = n1 == 0 ? 0 : graph[0].length;
        int[] match = new int[n2];
        Arrays.fill(match, -1);
        int matchCount = 0;
        for (int u = 0; u < n1; u++) {
            boolean[] visited = new boolean[n1];
            if (dfsMatch(u, graph, match, visited))
                matchCount++;
        }
        return matchCount;
    }

    boolean dfsMatch(int u, boolean[][] g, int[] match, boolean[] visited) {
        visited[u] = true;
        for (int v = 0; v < match.length; v++) {
            if (g[u][v] && (match[v] == -1 || !visited[match[v]] && dfsMatch(match[v], g, match, visited))) {
                match[v] = u;
                return true;
            }
        }
        return false;
    }

    String nextToken() throws IOException {
        while (tokens == null || !tokens.hasMoreTokens()) {
            String line = inStream.readLine();
            if (line == null) {
                isEOF = true;
                return null;
            }
            tokens = new StringTokenizer(line);
        }
        return tokens.nextToken();
    }

    int getNextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    void printLine(Object o) {
        outStream.println(o);
    }

    public CFA() throws IOException {
        inStream = new BufferedReader(new InputStreamReader(System.in));
        outStream = new PrintWriter(System.out);
        execute();
        outStream.close();
    }

    public static void main(String[] args) throws IOException {
        new CFA();
    }
}
